    stack = []
    for i in range(n):
        while stack and stack[-1] <= a[i]:
            stack.pop()
        stack.append(a[i])
    if len(stack) == n:
        return "NO"
    res = [0] * n
    for i in range(n):
        if a[i] == stack[-1]:
            res[i] = 1
            stack.pop()
