def split_sequence(a):
    n = len(a)
    if n == 1:
        return "YES", [0]

    inc_idx, dec_idx = None, None

    # Find the index where the sequence transitions from increasing to decreasing
    for i in range(1, n):
        if a[i] <= a[i - 1]:
            if inc_idx is None:
                inc_idx = i - 1
            else:
                break

    # If no such transition is found, the sequence is entirely increasing or decreasing
    if inc_idx is None or dec_idx is None:
        return "NO", []

    # Check if the remaining part forms a valid decreasing sequence
    for i in range(dec_idx + 1, n):
        if a[i] >= a[i - 1]:
            return "NO", []

    # Assign labels to the sequence
    res = [1 if i >= inc_idx else 0 for i in range(n)]

    return "YES", res

