    boundary = -1
    for i in range(1, n):
        if a[i] < a[i - 1]:
            boundary = i - 1
            break

    if boundary == -1:
        return "YES\n0"

    for i in range(boundary + 1, n - 1):
        if a[i] < a[i - 1]:
            return "NO"

    if a[-1] < a[-2]:
        return "NO"

    result = [1] * (boundary + 1) + [0] * (n - boundary - 1)
    return "YES\n" + ' '.join(map(str, result))

