def split_sequence(a):
    n = len(a)
    if n == 1:
        return "NO"

    # Find the longest increasing subsequence ending at each position
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if a[i] > a[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Find the longest decreasing subsequence starting at each position
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if a[i] > a[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Try to merge the longest increasing and decreasing subsequences
    for i in range(1, n-1):
        if lis[i-1] > 0 and lds[i+1] > 0:
            inc = a[:i]
            dec = a[i:]
            dec.reverse()
            merged = inc + dec[1:]
            if all(merged[j] < merged[j+1] for j in range(len(inc)-1)) and all(merged[k] > merged[k+1] for k in range(len(dec)-1)):
                res = [0]*len(inc) + [1]*(len(dec)-1)
                return "YES\n" + " ".join(map(str, res))

    return "NO"

